package gov.takx.api.systemmessage;

import com.google.common.base.MoreObjects;
import gov.takx.api.logging.SystemLogLevel;
import gov.takx.core.systemmessage.SystemMessageManager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A system message is an event either generated by a log4j message at the proper level, or by a call
 * to the {@link SystemMessageManager} to create one.  System events are timestamped, have a level, message,
 * an optional exception, and optional action callbacks.
 *
 * @since 1.43
 */
public class SystemMessage
{
    private final long timestamp = System.currentTimeMillis();
    private final SystemLogLevel level;
    private final String message;
    private Throwable exception;
    private List<MessageAction> actions;

    /**
     * Construct a system action with no exception and no actions.
     *
     * @param level   Message level
     * @param message Message text
     */
    public SystemMessage(SystemLogLevel level, String message)
    {
        this(level, message, null, null);
    }

    /**
     * Construct a system message with an exception.
     *
     * @param level     Message level
     * @param message   Message text
     * @param exception Exception to include in message, may be {@code null} if none
     */
    public SystemMessage(SystemLogLevel level, String message, Throwable exception)
    {
        this(level, message, exception, null);
    }

    /**
     * Construct a system message with actions and no exception.
     *
     * @param level   Message level
     * @param message Message text
     * @param actions List of actions, may be {@code null} if none
     */
    public SystemMessage(SystemLogLevel level, String message, List<MessageAction> actions)
    {
        this(level, message, null, actions);
    }

    /**
     * Construct a system message with actions.
     *
     * @param level     Message level
     * @param message   Message text
     * @param exception Exception to include in message, may be {@code null} if none
     * @param actions   List of actions, may be {@code null} if none
     */
    public SystemMessage(SystemLogLevel level, String message, Throwable exception, List<MessageAction> actions)
    {
        this.level = level;
        this.message = message;
        this.exception = exception;
        this.actions = actions;
    }

    public long getTimestamp()
    {
        return timestamp;
    }

    public SystemLogLevel getLevel()
    {
        return level;
    }

    public String getMessage()
    {
        return message;
    }

    /**
     * @return {@code true} if an exception was registered for this message
     */
    public boolean hasException()
    {
        return exception != null;
    }

    /**
     * Set the exception registered with this message.
     *
     * @param exception Exception to register
     */
    public void setException(Throwable exception)
    {
        this.exception = exception;
    }

    /**
     * @return Exception recorded on this message, may be {@code null}
     */
    public Throwable getException()
    {
        return exception;
    }

    /**
     * @return {@code true} if there are any actions registered for this message
     */
    public boolean hasActions()
    {
        return actions != null && !actions.isEmpty();
    }

    /**
     * Add an action to the current set of actions.
     *
     * @param action Action to add to list
     */
    public void addAction(MessageAction action)
    {
        if (actions == null) actions = new ArrayList<>();

        actions.add(action);
    }

    /**
     * @return List of actions registered for this message, may be {@code null}
     */
    public List<MessageAction> getActions()
    {
        return actions == null ? null : Collections.unmodifiableList(actions);
    }

    @Override
    public String toString()
    {
        return MoreObjects.toStringHelper(this)
                .add("level", level)
                .add("message", message)
                .toString();
    }
}
